import csv
import json
import math
import statistics

FICHIER = "mesures.csv"
NUMERIQUES = ["duree_session", "nb_clics", "score_avant", "score_apres"]
CIBLE = "churn"


def charger(path):
    with open(path, newline="", encoding="utf-8") as fichier:
        lignes = list(csv.DictReader(fichier))
    for ligne in lignes:
        for colonne in NUMERIQUES:
            ligne[colonne] = float(ligne[colonne])
    return lignes


def quartile(valeurs, position):
    tri = sorted(valeurs)
    index = (len(tri) - 1) * position
    bas = math.floor(index)
    haut = math.ceil(index)
    if bas == haut:
        return tri[bas]
    return tri[bas] + (tri[haut] - tri[bas]) * (index - bas)


def resume(valeurs):
    q1 = quartile(valeurs, 0.25)
    q3 = quartile(valeurs, 0.75)
    ecart = statistics.pstdev(valeurs) if len(valeurs) > 1 else 0.0
    asymetrie = (statistics.mean(valeurs) - statistics.median(valeurs)) / (ecart or 1.0)
    return {
        "moyenne": statistics.mean(valeurs),
        "mediane": statistics.median(valeurs),
        "ecart_type": ecart,
        "q1": q1,
        "q3": q3,
        "iqr": q3 - q1,
        "asymetrie": asymetrie,
        # asymetrie forte : on retient la mediane comme valeur typique
        "mesure_typique": "mediane" if abs(asymetrie) > 1 else "moyenne",
    }


def pearson(xs, ys):
    n = len(xs)
    moy_x = statistics.mean(xs)
    moy_y = statistics.mean(ys)
    covariance = sum((x - moy_x) * (y - moy_y) for x, y in zip(xs, ys)) / n
    var_x = math.sqrt(sum((x - moy_x) ** 2 for x in xs) / n)
    var_y = math.sqrt(sum((y - moy_y) ** 2 for y in ys) / n)
    if var_x == 0 or var_y == 0:
        return 0.0
    return covariance / (var_x * var_y)


def aberrantes(valeurs):
    q1 = quartile(valeurs, 0.25)
    q3 = quartile(valeurs, 0.75)
    iqr = q3 - q1
    borne_basse = q1 - 1.5 * iqr
    borne_haute = q3 + 1.5 * iqr
    return [v for v in valeurs if v < borne_basse or v > borne_haute]


def detecter_fuites(lignes):
    suspectes = []
    # score_apres est mesure apres l'evenement que l'on cherche a predire
    if "score_apres" in lignes[0]:
        suspectes.append({
            "colonne": "score_apres",
            "raison": "mesuree apres la cible : elle revele le futur au modele",
        })
    if "score_avant" in lignes[0]:
        donnees = [l["score_avant"] for l in lignes]
        cibles = [1.0 if l.get(CIBLE) in ("1", "true", "True") else 0.0 for l in lignes]
        liaison = abs(pearson(donnees, cibles))
        if liaison > 0.9:
            suspectes.append({
                "colonne": "score_avant",
                "raison": f"correlation {liaison:.2f} avec la cible : quasi-doublon",
            })
    return suspectes


def split_temporel(lignes):
    tries = sorted(lignes, key=lambda l: l["date"])
    coupe = int(len(tries) * 0.8)
    return tries[:coupe], tries[coupe:]


if __name__ == "__main__":
    lignes = charger(FICHIER)
    rapport = {"resume": {}, "correlations": {}, "aberrantes": {}, "split": {}}

    series = {c: [l[c] for l in lignes] for c in NUMERIQUES}
    for colonne, valeurs in series.items():
        rapport["resume"][colonne] = resume(valeurs)
        outliers = aberrantes(valeurs)
        rapport["aberrantes"][colonne] = {
            "nombre": len(outliers),
            "valeurs": outliers[:10],
        }

    cles = list(series)
    for i, gauche in enumerate(cles):
        for droite in cles[i + 1:]:
            valeur = pearson(series[gauche], series[droite])
            rapport["correlations"][f"{gauche}~{droite}"] = round(valeur, 3)

    rapport["fuites_potentielles"] = detecter_fuites(lignes)
    train, test = split_temporel(lignes)
    rapport["split"] = {
        "type": "temporel",
        "entrainement": len(train),
        "test": len(test),
        "justification": (
            "un split aleatoire melange les periodes et laisse fuir des "
            "informations futures dans l'entrainement"
        ),
    }

    with open("rapport.json", "w", encoding="utf-8") as fichier:
        json.dump(rapport, fichier, indent=2, ensure_ascii=False)
    print(json.dumps(rapport, indent=2, ensure_ascii=False))
